// Writes src/lib/system-guides.ts: for every system page, the Journal guides that belong with it.
//
// WHY A GENERATED FILE: system pages are part of the main script, and the Journal (about 60 articles)
// must never be imported into it (it would add about 50 KB gzip to every page; see the runbook).
// So the few fields a system page needs (title, topic, card photo) are copied into a small file.
// `npm run build` runs this first, and the audit fails if the file is out of date.
//
// Which guides: every article that lists the system in its `systems` field. The most specific come
// first (articles about only this system, then ones listing few systems), then the ones where this
// system is listed first, then the Journal's own display order. Three are shown.
import fs from "node:fs";
import path from "node:path";
import url from "node:url";

const ROOT = path.resolve(path.dirname(url.fileURLToPath(import.meta.url)), "..");
const OUT = path.join(ROOT, "src/lib/system-guides.ts");
const SHOWN = 3;

const str = (src, key) => new RegExp(`\\b${key}:\\s*"((?:[^"\\\\]|\\\\.)*)"`).exec(src)?.[1];

export function buildSystemGuidesSource() {
  const jsrc = fs.readFileSync(path.join(ROOT, "src/lib/journal.ts"), "utf8");
  const manifest = JSON.parse(fs.readFileSync(path.join(ROOT, "src/lib/journal-images.json"), "utf8"));
  const fileOf = Object.fromEntries(
    [...jsrc.matchAll(/import (\w+) from "\.\/journal-articles\/([^"]+)";/g)].map((m) => [m[1], m[2]])
  );
  const listSrc = /export const JOURNAL: Article\[\] = \[([\s\S]*?)\];/.exec(jsrc)?.[1] ?? "";
  const order = [...listSrc.matchAll(/\b(\w+),/g)].map((m) => fileOf[m[1]]).filter(Boolean);

  const articles = order.map((file, displayIndex) => {
    const src = fs.readFileSync(path.join(ROOT, "src/lib/journal-articles", `${file}.ts`), "utf8");
    const systems = [...(/systems:\s*\[([^\]]*)\]/.exec(src)?.[1] ?? "").matchAll(/"([^"]+)"/g)].map((m) => m[1]);
    const card = manifest[str(src, "card")];
    return {
      slug: str(src, "slug"),
      title: str(src, "title"),
      topic: str(src, "topic"),
      systems,
      displayIndex,
      image: card.url ?? `/images/${card.file}.webp`,
      alt: card.alt,
      w: card.w,
      h: card.h,
    };
  });

  const bySystem = {};
  for (const a of articles) for (const s of a.systems) (bySystem[s] ??= []).push({ a, rank: a.systems.indexOf(s) });

  const entries = Object.keys(bySystem)
    .sort()
    .map((s) => {
      const list = bySystem[s].sort(
        (x, y) =>
          x.a.systems.length - y.a.systems.length || x.rank - y.rank || x.a.displayIndex - y.a.displayIndex
      );
      const items = list.slice(0, SHOWN).map(({ a }) => ({
        slug: a.slug, title: a.title, topic: a.topic, image: a.image, alt: a.alt, w: a.w, h: a.h,
      }));
      return `  ${JSON.stringify(s)}: { total: ${list.length}, items: ${JSON.stringify(items, null, 2).replace(/\n/g, "\n    ")} },`;
    });

  return `// GENERATED by scripts/make-system-guides.mjs from the Journal articles. Do not edit by hand:
// \`npm run build\` regenerates it, and the audit fails if it is out of date.
// It is a small copy on purpose: system pages are in the main script and must not import the Journal.

export interface SystemGuide {
  slug: string;
  title: string;
  topic: string;
  /** Card photo path or full URL (720x480). */
  image: string;
  alt: string;
  w: number;
  h: number;
}

export const SYSTEM_GUIDES: Record<string, { total: number; items: SystemGuide[] }> = {
${entries.join("\n")}
};
`;
}

if (import.meta.url === url.pathToFileURL(process.argv[1] ?? "").href) {
  const next = buildSystemGuidesSource();
  const cur = fs.existsSync(OUT) ? fs.readFileSync(OUT, "utf8").replace(/\r\n/g, "\n") : "";
  if (cur !== next) fs.writeFileSync(OUT, next);
  console.log(cur === next ? "system-guides.ts is up to date" : "system-guides.ts written");
}
